        	var labelTextPair = [['ALL_MODULE_COUNT', gridObj.getRowsNum()], ['PRE_SELECTED_MODULE_COUNT', $previousSelectedCount], ['SELECTED_MODULE_COUNT', gridObj.getSelectedRows('SELECTED').length]]

			for( let [ btnId, textValue ] of labelTextPair ){
			    buttonbox.btn(btnId).setText(sUtils.string.dataReplacer(Sepoa.cache.text.get('BUTTON.GRID_ROW_COUNT_TEMPLATE'), {
			        LABEL: Sepoa.cache.text.get('AD_403.' + btnId),
			        TEXT: textValue
			    }));
			}


collapseFlag = flag;

if(flag === true) {
    gridObj.collapseAll();
} else if(flag === false) {
    gridObj.expandAll();
}


	if(houseCode && companyCode){
		$clientCode = houseCode;
		$companyCode = companyCode;	
	}

	dataOutput.setValue("COMPANY_CODE", $companyCode);
    dataOutput.setValue("HOUSE_CODE", $clientCode);

    var params = [];
    params.push('mode=doTreeGridQuery');
    params.push('PROCESS_ID=sepoa.svc.admin.AD_403');
    params.push('METHOD=doTreeGridQuery');
    gridObj.postConnection('/SepoaGrid.sux', params);


            var msg = obj.getUserData("", "message");
            var status = obj.getUserData("", "status");
            if (status == "false") {
                Alert(msg);
            }

            var rowCount = gridObj.getRowsNum();

            for(var i = 0; i < rowCount; i++) {
            	var rowID = gridObj.getRowId(i);
            	var rowData = gridObj.getRowDataObject(rowID);
            	var nodeType = rowData.NODE;
            	var extensionType = rowData.TYPE;
            	var extensionOptions = rowData.OPTIONS
            	var extensionIdx = gridObj.getColIndexById('EXTENSION');

            	if(nodeType == 'CONDITION') {

            		if(extensionType == 'POPUP') {
            			//gridObj.changeCellType(gridObj.getRowById(rowID), extensionIdx, 'ro');
            		} else if(extensionType == 'COMBO') {
            			gridObj.changeCellType(gridObj.getRowById(rowID), extensionIdx, 'comboro');

            			var code = extensionOptions.split(',')[0];
            			var param = extensionOptions.split(',')[1];
            			var cell = gridObj.cells(rowID, extensionIdx);

            			cell.initCombo();

            			if(param) {
            				param = window.dhx4.comboParam(param);
            			} else {
            				param = "";
            			}

            			var comboData = sUtils.cache.combo.get(code+","+param);

            			if(comboData) {
            				for(var idx in comboData) {
            					var combo = comboData[idx];

            					cell.getCellCombo().addOption(combo.value, combo.text);
            				}
            			}

            		} else if(extensionType == 'INEQUALITY') {

            		} else {
                        gridObj.changeCellType(gridObj.getRowById(rowID), extensionIdx, 'ed');
                    }
            	} else {
            		var cell = gridObj.cells(rowID, extensionIdx);

					cell.setValue('');
            	}
            }

            doServiceAjax('sepoa.svc.admin.AD_403', 'CONNECTION', 'doQueryFilteredData', {HOUSE_CODE: dataOutput.getValue("HOUSE_CODE")}, function(so) {
            	if(so.status != 1) {
            		Alert(Sepoa.cache.text.get('AD_403.FILTERED_DATA_LOAD_FAIL'));
            		return;
            	}

            	var sf = new SepoaFormater(so.result[0]);
            	$previousSelectedCount = sf.getRowCount();

            	if(sf.getRowCount() > 0) {
            		var sfList = sf.getArrayMap();
            		var dataPack = {};

            		for(var idx in sfList) {
            			var item = sfList[idx];

            			dataPack[item.MODULE] = {'OPTIONS': item.OPTIONS};
            		}

            		var gridRowCount = gridObj.getRowsNum();
            		var convertInequality = function(str) {
            			switch(str) {
            				case 'lt': return '<';
            				case 'gt': return '>';
            				case 'eq': return '==';
            				case 'ne': return '!=';
            			}
            		}

            		for(var i = 0 ; i < gridRowCount; i++) {
            			var rID = gridObj.getRowId(i);
            			var rowData = gridObj.getRowDataObject(rID);

            			if(dataPack[rowData.MODULE]) {
            				var selectedIdx = gridObj.getColIndexById('SELECTED');

            				gridObj.cells(rID, selectedIdx).setChecked(true);

            				if(rowData.NODE == 'CONDITION') {
	            				var viewIdx = gridObj.getColIndexById('EXTENSION');
	            				var extensionIdx = gridObj.getColIndexById('EXTENSION_VALUE');

	            				gridObj.cells(rID, viewIdx).setValue(dataPack[rowData.MODULE].OPTIONS);
	            				gridObj.cells(rID, extensionIdx).setValue(dataPack[rowData.MODULE].OPTIONS);

	            				if(rowData.TYPE == 'INEQUALITY') {
	            					var options = dataPack[rowData.MODULE].OPTIONS.split(',');
	            					var inequality = options[0];
	            					var value = options[1];

	            					gridObj.cells(rID, viewIdx).setValue(convertInequality(inequality) + ' ' + value);
	            				}
	            			}
            			}
            		}
            	}
            }, false);


            setModuleCount();

            if(collapseFlag === undefined) {
                allCollapseExpand(true);
            }


        	gridObj.expandAll();
        	setModuleCount();
	        gridObj.editStop();

	        var rowCount = gridObj.getRowsNum();
	        var selectRows = gridObj.getSelectedRows('SELECTED');

	        for(var idx in selectRows) {
	        	var rID = selectRows[idx];
	        	var rowData = gridObj.getRowDataObject(rID);

	        	if(rowData.NODE == 'CONDITION') {
	        		if(!rowData.EXTENSION_VALUE) {
                        Alert(Sepoa.cache.text.get('AD_403.EXTENSION_INVALIDATE') + rowData.DESCRIPTION);
	        			return;
	        		}
	        	}
	        }

	        Confirm(selectRows.length + Sepoa.cache.text.get('AD_403.SAVE_CONFIRM'), function(result) {
	            if (result) {
	                var params = [];
	                params.push('mode=doSave');
	                params.push('PROCESS_ID=sepoa.svc.admin.AD_403');
	                params.push('METHOD=doSave');
	                gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', params, 'SELECTED');
	            }
	        });


var mode = obj.mode;
var status = obj.status;
var message = obj.message;
if (status != 'true') {
    Alert(message);
}

Alert(Sepoa.cache.text.get('MESSAGE.0001'));
doQuery();


var header = gridObj.getColumnId(cIn);

if(header == 'EXTENSION') {
	var rowData = gridObj.getRowDataObject(rID);

	if(rowData.TYPE == 'POPUP') {
		var extensionOptions = rowData.OPTIONS;
		var code = extensionOptions.split(',')[0];
		var param = extensionOptions.split(',')[1];

		if(param) {
			param = window.dhx4.comboParam(param);
			param = param.split('#');
		} else {
			param = [];
		}

		currentSelectedRow = rID;
		PopupCommonPost(code, extensionPopupCallback, param);
	} else if(rowData.TYPE == 'INEQUALITY') {
		PopupOpenPost('/Admin/ModuleConfiguration/AdminModuleConfigurationInequalityPopup.sux', {selectedValue: rowData.EXTENSION_VALUE, rowID: rID}, inequalityPopupCallback, 400, 200, Sepoa.cache.text.get('AD_403.INEQUALITY_POPUP_TITLE'), 'INEQUALITY_POPUP');
	}
}

setModuleCount();


var viewIdx = gridObj.getColIndexById('EXTENSION');
var valueIdx = gridObj.getColIndexById('EXTENSION_VALUE');
var selectedIdx = gridObj.getColIndexById('SELECTED');

gridObj.cells(currentSelectedRow, viewIdx).setValue(code);
gridObj.cells(currentSelectedRow, valueIdx).setValue(code);

gridObj.cells(currentSelectedRow, selectedIdx).setChecked(true);


        	var selectedIdx = gridObj.getColIndexById('SELECTED');
        	var viewIdx = gridObj.getColIndexById('EXTENSION');
        	var extensionValueIdx = gridObj.getColIndexById('EXTENSION_VALUE');
        	var rID = params.rowID;

        	if(data) {
				var inequalityType = data.INEQUALITY_TYPE;
				var text = data.INEQUALITY_TYPE_STR;
	        	var value = data.VALUE;

	        	gridObj.cells(rID, viewIdx).setValue(text + ' ' + value);
