	        	gridObj.cells(rID, extensionValueIdx).setValue('');
        		gridObj.cells(rID, selectedIdx).setChecked(false);
        	}


        	setModuleCount();

        	var header = gridObj.getColumnId(cIn)

        	if(stage == 0) {
        		if(header == 'REMARK') {
        			return false;
        		}
        		return true;
    		} else if(stage == 1) {
	    		return true;
        	} else if(stage == 2) {
        		if(header == 'EXTENSION') {
        			var rowData = gridObj.getRowDataObject(rID);
        			var valueColumnIdx = gridObj.getColIndexById('EXTENSION_VALUE');

        			gridObj.cells(rID, valueColumnIdx).setValue(nValue);
        		}
        		return true;
        	}
